const item = $input.first().json;
if (item.exitCode !== 0) {
  throw new Error('discover_leaflets.py failed: ' + (item.stderr || 'unknown error'));
}
let parsed;
try {
  parsed = JSON.parse(item.stdout);
} catch (e) {
  throw new Error('discover_leaflets.py returned invalid JSON: ' + e.message);
}
const leaflets = parsed.leaflets || [];
return leaflets.map(l => ({ json: l }));

const hashCheck = $input.first().json;
let existingHashes = new Set();
if (hashCheck.exitCode === 0) {
  try {
    const rows = hashCheck.stdout ? JSON.parse(hashCheck.stdout) : [];
    existingHashes = new Set(rows.map(r => r.content_hash));
  } catch (e) {
    throw new Error('Could not parse existing leaflet hashes: ' + e.message);
  }
} else {
  throw new Error('Failed to query leaflets table: ' + (hashCheck.stderr || 'unknown error'));
}
const discovered = $('Parse Discovered Leaflets').all().map(i => i.json);
const fresh = discovered.filter(l => l.content_hash && !existingHashes.has(l.content_hash));
return fresh.map(l => ({ json: l }));

const staticData = $getWorkflowStaticData('global');
const success = staticData.successCount || 0;
const errors = staticData.errorCount || 0;
const total = success + errors;
const errorRate = total > 0 ? errors / total : 0;
staticData.successCount = 0;
staticData.errorCount = 0;
return [{ json: { success, errors, total, errorRate, alert: errorRate > 0.3 } }];

const item = $input.first().json;
const leafletId = $('Loop New Leaflets').item.json.leaflet_id;
if (item.exitCode !== 0) {
  throw new Error('download_leaflet.py failed for ' + leafletId + ': ' + (item.stderr || 'unknown error'));
}
let parsed;
try {
  parsed = JSON.parse(item.stdout);
} catch (e) {
  throw new Error('download_leaflet.py returned invalid JSON for ' + leafletId + ': ' + e.message);
}
const pages = parsed.pages || [];
return pages.map(p => ({ json: { leaflet_id: leafletId, page_path: p } }));

const leafletId = $('Loop New Leaflets').item.json.leaflet_id;
const leaflet = $('Loop New Leaflets').item.json;
const parseResult = $input.first().json;
if (parseResult.exitCode !== 0) {
  throw new Error('parse_offers.py failed for ' + leafletId + ': ' + (parseResult.stderr || 'unknown error'));
}
let offers = [];
try {
  offers = (JSON.parse(parseResult.stdout).offers) || [];
} catch (e) {
  throw new Error('parse_offers.py returned invalid JSON for ' + leafletId + ': ' + e.message);
}
const offersJson = JSON.stringify(offers);
const leafletJson = JSON.stringify({
  leaflet_id: leafletId,
  retailer: leaflet.retailer,
  content_hash: leaflet.content_hash,
  source_url: leaflet.source_url,
  processed_at: new Date().toISOString(),
  offer_count: offers.length
});
const tmpFile = '/tmp/grocery_offers_' + leafletId.replace(/[^a-zA-Z0-9_-]/g, '_') + '.json';
const shell =
  'cat > ' + tmpFile + " << 'OFFERSEOF'\n" +
  offersJson + '\n' +
  "OFFERSEOF\n" +
  'sqlite3 "$GROCERY_DB" << \'SQLEOF\'\n' +
  'BEGIN;\n' +
  "INSERT OR REPLACE INTO leaflets (leaflet_id, retailer, content_hash, source_url, processed_at, offer_count) VALUES (" +
  "'" + leafletId.replace(/'/g, "''") + "', " +
  "'" + String(leaflet.retailer || '').replace(/'/g, "''") + "', " +
  "'" + String(leaflet.content_hash || '').replace(/'/g, "''") + "', " +
  "'" + String(leaflet.source_url || '').replace(/'/g, "''") + "', " +
  "'" + new Date().toISOString() + "', " +
  offers.length + ');\n' +
  "INSERT OR IGNORE INTO offers (leaflet_id, retailer, product_name, brand, capacity, price, unit_price, valid_from, valid_to, requires_card, purchase_limit, page, confidence, raw_text)\n" +
  "SELECT '" + leafletId.replace(/'/g, "''") + "', value->>'retailer', value->>'product_name', value->>'brand', value->>'capacity', value->>'price', value->>'unit_price', value->>'valid_from', value->>'valid_to', value->>'requires_card', value->>'purchase_limit', value->>'page', value->>'confidence', value->>'raw_text'\n" +
  "FROM json_each(readfile('" + tmpFile + "'));\n" +
  'COMMIT;\n' +
  "SQLEOF\n" +
  'rm -f ' + tmpFile + ';\n';
return [{ json: { leaflet_id: leafletId, offer_count: offers.length, shell_cmd: shell } }];

const staticData = $getWorkflowStaticData('global');
staticData.successCount = (staticData.successCount || 0) + 1;
const dbResult = $input.first().json;
const meta = $('Build Leaflet+Offers SQL').first().json;
if (dbResult.exitCode !== 0) {
  staticData.errorCount = (staticData.errorCount || 0) + 1;
  staticData.successCount -= 1;
  console.log('SQLite write failed for ' + meta.leaflet_id + ': ' + (dbResult.stderr || 'unknown error'));
} else {
  console.log('Processed leaflet ' + meta.leaflet_id + ' with ' + meta.offer_count + ' offers.');
}
return [{ json: { leaflet_id: meta.leaflet_id, offer_count: meta.offer_count, processed_at: new Date().toISOString() } }];

